import re
from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class MpucchFddParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]
        self.ch_bw = None

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.ch_bw = float(re.match(r'(.*) MHz', self.cell_ent.get('ch_bw', '10 MHz')).group(1))

        self.set_riEnable()
        self.set_maxNumRrcEmergency(execution_config)
        self.set_chBw_dependencies(execution_config)

    def set_riEnable(self):
        dl_mimo_mode = self.cell_ent.get('dl_mimo_mode', '')
        if dl_mimo_mode == 'Dynamic Open Loop MIMO' or re.match(r'Closed Loop', dl_mimo_mode, re.I):
            self.set_parameter('riEnable', 'true')

    def set_maxNumRrcEmergency(self, execution_config):
        if 'max_num_rrc_emergency' in self.cell_ent:
            maxNumRrcEmergency = self.cell_ent['max_num_rrc_emergency']

        elif int(self.ch_bw) <= 5:
            maxNumRrcEmergency = 45
        else:
            if execution_config['is_fsm4']:
                maxNumRrcEmergency = 315
            else:
                maxNumRrcEmergency = 420
        self.set_parameter('maxNumRrcEmergency', maxNumRrcEmergency)

    def set_chBw_dependencies(self, execution_config):
        if int(self.ch_bw) <= 5:
            self.set_parameter('addAUeRrHo', 10)
            self.set_parameter('deltaPucchShift', 1)
            self.set_parameter('maxNumRrc', 15)
            self.set_parameter('nCqiRb', 1)

        else:
            self.set_parameter('deltaPucchShift', 2)
            self.set_parameter('nCqiRb', 2)
            self.set_parameter('cqiPerNp', '40ms')
            self.set_parameter('n1PucchAn', 36)

            if execution_config['is_fsm4']:
                self.set_parameter('addAUeRrHo', 60)
                self.set_parameter('maxNumRrc', 245)
            else:
                self.set_parameter('addAUeRrHo', 15)
                self.set_parameter('maxNumRrc', 300)

        if int(self.ch_bw) <= 1:
            self.set_parameter('cqiPerNp', '10ms')
            self.set_parameter('n1PucchAn', 30)
        elif int(self.ch_bw) <= 3:
            self.set_parameter('cqiPerNp', '20ms')
            self.set_parameter('n1PucchAn', 24)
        elif int(self.ch_bw) <= 5:
            self.set_parameter('cqiPerNp', '10ms')
            self.set_parameter('n1PucchAn', 36)
